        "check_name": "csv_format_t01",
        "description": "Verify t01_selected_indicators.csv has valid CSV format and required columns",
        "check_func": lambda: check_csv_format("outputs/t01_selected_indicators.csv", ["indicator_id", "indicator_name", "theme", "justification", "expected_direction"]),
    },
    # Check 4: CSV format validation for t05_clean_stops.csv
    {
        "check_name": "csv_format_t05",
        "description": "Verify t05_clean_stops.csv has valid CSV format and required columns",
        "check_func": lambda: check_csv_format("outputs/t05_clean_stops.csv", ["stop_id", "stop_name", "stop_lat", "stop_lon"]),
    },
    # Check 5: CSV format validation for t08_pois_clean.csv
    {
        "check_name": "csv_format_t08",
        "description": "Verify t08_pois_clean.csv has valid CSV format and required columns",
        "check_func": lambda: check_csv_format("outputs/t08_pois_clean.csv", ["qid", "label", "poi_type", "latitude", "longitude", "source"]),
    },
    # Check 6: CSV format validation for t10_accessibility_scores.csv
    {
        "check_name": "csv_format_t10",
        "description": "Verify t10_accessibility_scores.csv has valid CSV format and required columns",
        "check_func": lambda: check_csv_format("outputs/t10_accessibility_scores.csv", ["qid", "label", "poi_type", "distance_m", "n_departures", "n_routes", "accessibility_score"]),
    },
    # Check 7: CSV format validation for t13_city_clusters.csv
    {
        "check_name": "csv_format_t13",
        "description": "Verify t13_city_clusters.csv has valid CSV format and required columns",
        "check_func": lambda: check_csv_format("outputs/t13_city_clusters.csv", ["city_id", "city_name", "year", "cluster_id"]),
    },
    # Check 8: Data integrity for t01_selected_indicators.csv (no duplicate indicator_ids)
    {
        "check_name": "no_duplicates_t01",
        "description": "Verify t01_selected_indicators.csv has no duplicate indicator_ids",
        "check_func": lambda: check_no_duplicates("outputs/t01_selected_indicators.csv", "indicator_id"),
    },
    # Check 9: Numeric validation for t05_clean_stops.csv (lat/lon are numeric)
    {
        "check_name": "numeric_coords_t05",
        "description": "Verify t05_clean_stops.csv has numeric stop_lat and stop_lon values",
        "check_func": lambda: check_numeric_coords("outputs/t05_clean_stops.csv", ["stop_lat", "stop_lon"]),
    },
    # Check 10: Numeric validation for t10_accessibility_scores.csv (accessibility_score is between 0 and 1)
    {
        "check_name": "score_range_t10",
        "description": "Verify t10_accessibility_scores.csv has accessibility_score between 0 and 1",
        "check_func": lambda: check_score_range("outputs/t10_accessibility_scores.csv", "accessibility_score"),
    },
]


def check_file_exists():
    """Check that all expected output files exist."""
    results = []
    for filepath in OUTPUT_FILES:
        if os.path.exists(filepath):
            results.append({
                "check_name": "file_exists",
                "passed": True,
                "message": f"File {filepath} exists",
            })
        else:
            results.append({
                "check_name": "file_exists",
                "passed": False,
                "message": f"File {filepath} does not exist",
            })
    return results


def check_file_non_empty():
    """Check that all expected output files are non-empty."""
    results = []
    for filepath in OUTPUT_FILES:
        if os.path.exists(filepath) and os.path.getsize(filepath) > 0:
            results.append({
                "check_name": "file_non_empty",
                "passed": True,
                "message": f"File {filepath} is non-empty",
            })
        else:
            results.append({
                "check_name": "file_non_empty",
                "passed": False,
                "message": f"File {filepath} is empty or does not exist",
            })
    return results


def check_csv_format(filepath, required_columns):
    """Check that a CSV file has valid format and required columns."""
    results = []
    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            reader = csv.reader(f)
            header = next(reader)

            # Check if all required columns exist
            missing_cols = [col for col in required_columns if col not in header]
            if missing_cols:
                results.append({
                    "check_name": "csv_format_t01",
                    "passed": False,
                    "message": f"t01_selected_indicators.csv missing columns: {missing_cols}",
                })
                return results

            # Check if file has data rows
            row_count = sum(1 for _ in reader)
            if row_count == 0:
                results.append({
                    "check_name": "csv_format_t01",
                    "passed": False,
                    "message": f"t01_selected_indicators.csv has no data rows",
                })
                return results

            results.append({
                "check_name": "csv_format_t01",
                "passed": True,
                "message": f"t01_selected_indicators.csv has valid format with {row_count} data rows",
            })
    except Exception as e:
        results.append({
            "check_name": "csv_format_t01",
            "passed": False,
            "message": f"t01_selected_indicators.csv error: {str(e)}",
        })
    return results


def check_no_duplicates(filepath, column_name):
    """Check that a CSV file has no duplicate values in the specified column."""
    results = []
    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            reader = csv.DictReader(f)
            seen = set()
            duplicates = []
            for row in reader:
                value = row.get(column_name, '')
                if value in seen:
                    duplicates.append(value)
                seen.add(value)

            if duplicates:
                results.append({
                    "check_name": "no_duplicates_t01",
                    "passed": False,
                    "message": f"t01_selected_indicators.csv has duplicate {column_name}: {duplicates[:5]}...",
                })
            else:
                results.append({
                    "check_name": "no_duplicates_t01",
                    "passed": True,
                    "message": f"t01_selected_indicators.csv has no duplicate {column_name}",
                })
    except Exception as e:
        results.append({
            "check_name": "no_duplicates_t01",
            "passed": False,
            "message": f"t01_selected_indicators.csv error: {str(e)}",
        })
    return results


def check_numeric_coords(filepath, columns):
    """Check that specified columns in a CSV file contain numeric values."""
    results = []
    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            reader = csv.DictReader(f)
            for row in reader:
                for col in columns:
                    value = row.get(col, '')
                    # Skip empty values
                    if value:
                        try:
                            float(value)
                        except ValueError:
                            results.append({
                                "check_name": "numeric_coords_t05",
                                "passed": False,
                                "message": f"t05_clean_stops.csv has non-numeric {col}: {value}",
                            })
                            return results
        results.append({
            "check_name": "numeric_coords_t05",
            "passed": True,
            "message": f"t05_clean_stops.csv has numeric values for {', '.join(columns)}",
        })
    except Exception as e:
        results.append({
            "check_name": "numeric_coords_t05",
            "passed": False,
            "message": f"t05_clean_stops.csv error: {str(e)}",
        })
    return results


def check_score_range(filepath, column_name):
    """Check that a column in a CSV file has values within a specific range."""
    results = []
    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            reader = csv.DictReader(f)
            min_val = float('inf')
            max_val = float('-inf')
            out_of_range = []
            for row in reader:
                value = row.get(column_name, '')
                if value:
                    try:
                        num_val = float(value)
                        if num_val < min_val:
                            min_val = num_val
                        if num_val > max_val:
                            max_val = num_val
                        if num_val < 0 or num_val > 1:
                            out_of_range.append(value)
                    except ValueError:
                        pass

            if out_of_range:
                results.append({
                    "check_name": "score_range_t10",
                    "passed": False,
                    "message": f"t10_accessibility_scores.csv has values outside [0,1] for {column_name}: {out_of_range[:5]}...",
                })
            else:
                results.append({
                    "check_name": "score_range_t10",
                    "passed": True,
                    "message": f"t10_accessibility_scores.csv has {column_name} in range [0,1] (range: [{min_val:.4f}, {max_val:.4f}])",
                })
    except Exception as e:
        results.append({
            "check_name": "score_range_t10",
            "passed": False,
            "message": f"t10_accessibility_scores.csv error: {str(e)}",
        })
    return results


def main():
    """Main entry point for the validation script."""
    all_results = []

    # Run all checks
    for check in CHECKS:
        results = check["check_func"]()
        all_results.extend(results)

    # Write results to JSON file
    output_path = "outputs/t14_validation_summary.json"
    with open(output_path, 'w', encoding='utf-8') as f:
        json.dump(all_results, f, indent=2)

    print(f"Validation complete. Results written to {output_path}")
    print(f"Total checks: {len(all_results)}")
    passed = sum(1 for r in all_results if r["passed"])
    print(f"Passed: {passed}/{len(all_results)}")

    # Exit with code 0 if all checks pass
    if passed == len(all_results):
        sys.exit(0)
    else:
        sys.exit(1)


if __name__ == "__main__":
    main()
