    results = []
    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            reader = csv.DictReader(f)
            min_val = float('inf')
            max_val = float('-inf')
            out_of_range = []
            for row in reader:
                value = row.get(column_name, '')
                if value:
                    try:
                        num_val = float(value)
                        if num_val < min_val:
                            min_val = num_val
                        if num_val > max_val:
                            max_val = num_val
                        if num_val < 0 or num_val > 1:
