    passed = sum(1 for r in all_results if r["passed"])
    print(f"Passed: {passed}/{len(all_results)}")

    # Exit with code 0 if all checks pass
    if passed == len(all_results):
        sys.exit(0)
    else:
        sys.exit(1)


