                    "check_name": "score_range_t10",
                    "passed": False,
                    "message": f"{filepath} has values outside [0,1] for {column_name}: {out_of_range[:5]}...",
                })
            else:
                results.append({
                    "check_name": "score_range_t10",
                    "passed": True,
                    "message": f"{filepath} has {column_name} in range [0,1] (range: [{min_val:.4f}, {max_val:.4f}])",
                })
    except Exception as e:
        results.append({
            "check_name": "score_range_t10",
            "passed": False,
            "message": f"{filepath} error: {str(e)}",
        })
    return results


def main():
    """Main entry point for the validation script."""
    all_results = []

    # Run all checks
    for check in CHECKS:
        results = check["check_func"]()
        all_results.extend(results)

    # Write results to JSON file
    output_path = "outputs/t14_validation_summary.json"
    with open(output_path, 'w', encoding='utf-8') as f:
        json.dump(all_results, f, indent=2)

    print(f"Validation complete. Results written to {output_path}")
    print(f"Total checks: {len(all_results)}")
    passed = sum(1 for r in all_results if r["passed"])
    print(f"Passed: {passed}/{len(all_results)}")

    # Exit with code 0 if all checks pass
    if passed == len(all_results):
        sys.exit(0)
    else:
        sys.exit(1)


if __name__ == "__main__":
    main()

